import{_ as o,o as d,c,a0 as t}from"./chunks/framework.OED5XGjC.js";const g=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),r={name:"explanation/concepts.md"};function n(a,e,s,i,l,h){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The vocabulary of the myco ledger — each term defined once.</p><h2 id="the-ledger" tabindex="-1">The ledger <a class="header-anchor" href="#the-ledger" aria-label="Permalink to &quot;The ledger&quot;">​</a></h2><ul><li><strong>Ledger</strong> — the <code>project/</code> worktree: the canonical record of intent for one repo. Markdown files on an orphan <code>project</code> branch; git history is the audit trail.</li><li><strong>Item</strong> — one unit of work or thought, with a prefixed id (<code>T-001</code> task, <code>I-001</code> issue, <code>P-001</code> proposal, <code>PL-001</code> plan, <code>ADR-0001</code> decision). Tasks are lines in <code>TODO.md</code>/<code>BACKLOG.md</code>/ <code>DONE.md</code>; the file-backed kinds get one markdown file each.</li><li><strong>Kind</strong> — the item type (<code>task</code>, <code>issue</code>, <code>proposal</code>, <code>adr</code>, <code>plan</code>, plus <code>[[kinds]]</code> customs). Each kind has a prefix, a storage shape (<code>doc</code> lines or <code>dir</code> files), and its own state vocabulary.</li><li><strong>State machine</strong> — the seven statuses (<code>open</code>, <code>claimed</code>, <code>in-progress</code>, <code>blocked</code>, <code>deferred</code>, <code>done</code>, <code>cancelled</code>) and the legal transitions between them. Verbs walk it one step at a time.</li><li><strong>Handoff</strong> — an append-only dated note on an item (<code>handoffs/&lt;ID&gt;.md</code>) recording done/next/open at session end. <code>resume</code> reads the latest entries back as restart context.</li><li><strong>View</strong> — a declarative read spec (<code>filter → group_by → sort → limit → format</code>) named in <code>[views]</code> config or built in (<code>board</code>, <code>open</code>, <code>epic</code>, <code>burnup</code>, …). Views are the <em>only</em> read surface — there are no per-view verbs.</li><li><strong>Verb</strong> — a mutation or read the engine owns (<code>todo add</code>, <code>item set</code>, <code>handoff</code>, <code>view</code>, …). Every mutating verb is one atomic commit on <code>project</code>.</li></ul><h2 id="engine-and-prelude" tabindex="-1">Engine and prelude <a class="header-anchor" href="#engine-and-prelude" aria-label="Permalink to &quot;Engine and prelude&quot;">​</a></h2><ul><li><strong>Engine</strong> — the code-owned half: file spec, state machine, id registry, commit-per-mutation, view evaluation. Must never be data.</li><li><strong>Prelude</strong> — the seeded config half: the five builtin <code>[[kinds]]</code>, the builtin views, the <code>[verbs]</code> aliases <code>myco init</code> writes into <code>myco.toml</code>. PM is the shipped prelude, not the product boundary.</li><li><strong>Index</strong> — the derived, disposable cache (redb + <code>repos.toml</code> under <code>~/.local/share/myco</code>) powering <code>status</code>/<code>view</code>/<code>org</code> reads. Markdown stays canonical; the index can be deleted and rebuilt.</li><li><strong>Universe</strong> — the set of repos an index-sourced view spans: lasius workspace clones ∪ <code>repos.toml</code> registrations.</li><li><strong>Ledger state</strong> — per universe repo: <code>local</code> (own <code>project/</code>), <code>none</code> (ledger-less — verbs resolve to the org ledger), or <code>org</code> (the one repo every <code>none</code> member points at).</li></ul><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><ul><li><strong><code>myco</code> command</strong> — a tamias <code>bins[]</code> shim: generated script → <code>tamias bin exec</code> → <code>tamias-driver-myco cli</code> → the engine lib. There is no cargo-installed <code>myco</code> binary.</li><li><strong><code>tamias-driver-myco</code></strong> — the driver binary: pavo view driver + engine ops surface (<code>ops</code> manifest, <code>cli.&lt;verb&gt;</code> queries, <code>cli</code> shim passthrough). Writes always ride the engine&#39;s verbs.</li><li><strong><code>myco ui</code></strong> — the ratatui board TUI, a front-end over <code>myco-ops</code>.</li><li><strong><code>myco serve</code> / <code>myco batch</code></strong> — the embedding surfaces: ndjson JSON-RPC over stdio for daemons, and one-shot batched requests for scripts and agent fan-out reads.</li></ul>',8)])])}const m=o(r,[["render",n]]);export{g as __pageData,m as default};
